using RailNarrator.Domain;
using RailNarrator.Pdf;
using RailNarrator.TestFixtures;
using Xunit;

namespace RailNarrator.Pdf.Tests;

/// <summary>
/// Extraction against real PDFs generated by <see cref="SyntheticPdf"/>.
/// </summary>
/// <remarks>
/// These run the actual RailReaderCore pipeline — PDFium text extraction, the model-free layout
/// analyzer, the XY-cut reading-order resolver and line detection — with no ONNX model, no GPU and no
/// network. That is deliberate: the geometry and reading-order guarantees the narration layer depends
/// on must hold in a plain CI environment, and a test that needs a 50 MB model download will not be
/// run often enough to catch a regression.
/// </remarks>
public sealed class ExtractionTests
{
    private static ExtractionOptions ModelFreeOptions { get; } = new(
        "text-layout", OcrPolicy.Off, 1024, DeskewLines: false, ExtractorVersions.Current);

    private static async Task<ExtractionSnapshot> ExtractAsync(string path, NarrationFilterSettings? filters = null)
    {
        using var source = new RailReaderExtractionSource();
        source.WithBackend(ExtractionBackend.ModelFree());
        return await source.ExtractAsync(new ExtractionRequest(
            path, null, null, ModelFreeOptions, filters ?? NarrationFilterSettings.Default));
    }

    [Fact]
    public async Task SingleColumn_ExtractsTextAndGeometry()
    {
        string path = SyntheticPdf.WriteSingleColumn(SyntheticPdf.TempPath("single"),
        [
            "The quick brown fox jumps over the lazy dog.",
            "Pack my box with five dozen liquor jugs.",
        ]);

        var snapshot = await ExtractAsync(path);

        Assert.Single(snapshot.Pages);
        var page = snapshot.Pages[0]!;
        Assert.Contains("quick brown fox", page.Text);
        Assert.Contains("liquor jugs", page.Text);
        Assert.True(page.Coverage.TextLayerPresent, "a born-digital page must report a native text layer");
        Assert.False(page.Coverage.OcrUsed);
        Assert.True(page.Coverage.CharCount > 40, $"expected substantial text, got {page.Coverage.CharCount} chars");
        Assert.NotEmpty(page.Blocks);
        Assert.NotEmpty(page.Lines);
        Assert.NotEmpty(page.Chars);
    }

    [Fact]
    public async Task ACropOfAPassageIsAPngOfItsInk()
    {
        // Every crop used to throw (an RGB pixmap installed as a four-byte format), and the maths
        // interpreter, which swallows a failed crop, silently worked from the text layer alone.
        string path = SyntheticPdf.WriteSingleColumn(SyntheticPdf.TempPath("crop"), ["The quick brown fox jumps over the lazy dog."]);
        using var source = new RailReaderExtractionSource();
        source.WithBackend(ExtractionBackend.ModelFree());
        var snapshot = await source.ExtractAsync(new ExtractionRequest(path, null, null, ModelFreeOptions, NarrationFilterSettings.Default));
        source.AttachDocument(path);
        var line = snapshot.Pages[0]!.Lines[0];

        var png = await source.RenderCropPngAsync(snapshot.Identity, 0, line.Rect, 800);

        Assert.NotNull(png);
        using var bitmap = SkiaSharp.SKBitmap.Decode(png.Value.ToArray());
        Assert.NotNull(bitmap);
        Assert.InRange(bitmap.Width, 790, 810);
        int dark = 0;
        for (int y = 0; y < bitmap.Height; y++)
            for (int x = 0; x < bitmap.Width; x++)
                if (bitmap.GetPixel(x, y).Red < 100) dark++;
        Assert.True(dark > bitmap.Width, $"expected the line's ink in the crop, found {dark} dark pixels");
    }

    [Fact]
    public async Task Snapshot_StampsCoordinateFrameAndIdentity()
    {
        string path = SyntheticPdf.WriteSingleColumn(SyntheticPdf.TempPath("frame"), ["Some text on the page."]);
        var snapshot = await ExtractAsync(path);

        // Geometry must declare the frame it is in, or a later rotation silently reinterprets it.
        Assert.Equal("page-point", snapshot.Frame.Units);
        Assert.Equal("top-left", snapshot.Frame.Origin);
        Assert.True(snapshot.Frame.CropApplied);
        Assert.False(string.IsNullOrEmpty(snapshot.Identity.DocumentContentHash));
        Assert.Equal(64, snapshot.Identity.DocumentContentHash.Length);
        Assert.Equal(1, snapshot.Identity.ExtractionRevision);
    }

    [Fact]
    public async Task ContentHash_IsStableAcrossPaths_AndChangesWithContent()
    {
        string a = SyntheticPdf.WriteSingleColumn(SyntheticPdf.TempPath("hash-a"), ["Identical content here."]);
        string b = SyntheticPdf.WriteSingleColumn(SyntheticPdf.TempPath("hash-b"), ["Identical content here."]);
        string c = SyntheticPdf.WriteSingleColumn(SyntheticPdf.TempPath("hash-c"), ["Different content here."]);

        var sa = await ExtractAsync(a);
        var sb = await ExtractAsync(b);
        var sc = await ExtractAsync(c);

        // Content-addressed, so a copied or renamed file keeps its caches.
        Assert.Equal(sa.Identity.DocumentContentHash, sb.Identity.DocumentContentHash);
        Assert.NotEqual(sa.Identity.DocumentContentHash, sc.Identity.DocumentContentHash);
    }

    [Fact]
    public async Task TwoColumn_ReadsLeftColumnBeforeRightColumn()
    {
        string path = SyntheticPdf.WriteTwoColumn(
            SyntheticPdf.TempPath("twocol"),
            left: ["Alpha one left column.", "Alpha two left column.", "Alpha three left column."],
            right: ["Bravo one right column.", "Bravo two right column.", "Bravo three right column."]);

        var snapshot = await ExtractAsync(path);
        var page = snapshot.Pages[0]!;

        var builder = new ReadingUnitBuilder(new ReadingUnitBuilderOptions(NarrationFilterSettings.Default));
        var units = builder.Build(snapshot);

        Assert.NotEmpty(units);
        string joined = string.Join(" ", units.Select(u => u.OriginalText));
        int lastAlpha = joined.LastIndexOf("Alpha", StringComparison.Ordinal);
        int firstBravo = joined.IndexOf("Bravo", StringComparison.Ordinal);

        Assert.True(lastAlpha >= 0, $"left column text missing from: {joined}");
        Assert.True(firstBravo >= 0, $"right column text missing from: {joined}");
        // The whole left column must be read before any of the right column. Interleaving line by
        // line is the classic two-column failure and reads as gibberish aloud.
        Assert.True(lastAlpha < firstBravo,
            $"reading order interleaved the columns: {joined}");
    }

    [Fact]
    public async Task RunningHeaderAndFooter_AreSuppressedByDefault()
    {
        string path = SyntheticPdf.WriteWithRunningElements(
            SyntheticPdf.TempPath("running"),
            header: "Journal of Reproducible Narration",
            footer: "Page",
            bodyLines: ["The body text that should actually be narrated aloud."],
            pageCount: 4);

        var snapshot = await ExtractAsync(path);
        var running = RunningElementDetector.Detect(snapshot, minPages: 3);

        Assert.NotEmpty(running);
        Assert.Contains(running, r => r.Kind == RunningElementKind.RepeatedHeader
                                      && r.NormalisedText.Contains("reproducible narration", StringComparison.Ordinal));
        Assert.Contains(running, r => r.Kind == RunningElementKind.PageNumber);

        var builder = new ReadingUnitBuilder(new ReadingUnitBuilderOptions(NarrationFilterSettings.Default));
        var units = builder.Build(snapshot);
        string joined = string.Join(" ", units.Select(u => u.OriginalText));

        Assert.Contains("body text", joined);
        Assert.DoesNotContain("Journal of Reproducible", joined);
    }

    [Fact]
    public async Task RunningHeader_IsKeptWhenTheFilterAllowsIt()
    {
        string path = SyntheticPdf.WriteWithRunningElements(
            SyntheticPdf.TempPath("running-kept"),
            header: "Running Header Text",
            footer: "Footer",
            bodyLines: ["Body content only."],
            pageCount: 3);

        var snapshot = await ExtractAsync(path);
        var filters = NarrationFilterSettings.Default with { ExcludeRunningHeaders = false };
        var builder = new ReadingUnitBuilder(new ReadingUnitBuilderOptions(filters));
        var units = builder.Build(snapshot);
        string joined = string.Join(" ", units.Select(u => u.OriginalText));

        // Compared with whitespace stripped: this test is about the filter toggle, and word-space
        // detection has its own test. Coupling the two would make a spacing regression look like a
        // filter regression.
        string normalised = new string(joined.Where(c => !char.IsWhiteSpace(c)).ToArray());
        Assert.Contains("Bodycontentonly", normalised, StringComparison.Ordinal);
        // The exclusion is an inspectable rule the reader can turn off, not a silent guess.
        Assert.Contains("RunningHeaderText", normalised, StringComparison.Ordinal);
    }

    [Fact]
    public async Task WordSpaces_AreRecoveredFromGlyphGeometry()
    {
        // The text layer of a real PDF is not a usable transcription: on this fixture the producer
        // embedded phantom characters inside words. Word spacing has to come from glyph geometry.
        string path = SyntheticPdf.WriteSingleColumn(SyntheticPdf.TempPath("spaces"),
            ["The body text is what a listener actually wants to hear."]);

        var snapshot = await ExtractAsync(path);
        var page = snapshot.Pages[0]!;
        Assert.Contains("Thebodytext", new string(page.Text.Where(c => !char.IsWhiteSpace(c)).ToArray()),
            StringComparison.Ordinal);

        var units = new ReadingUnitBuilder(new ReadingUnitBuilderOptions(NarrationFilterSettings.Default)).Build(snapshot);
        string joined = string.Join(" ", units.Select(u => u.OriginalText));

        Assert.Contains("The body text is what a listener actually wants to hear.", joined);
    }

    [Fact]
    public async Task RealHyphens_SurviveExtraction()
    {
        // A hyphen that is part of a word must not be removed. The trailing hyphen of the first line
        // used to vanish here, and that was put down to Skia's PDF writer. It was PDFium: a hyphen
        // that ends a line is reported as U+0002, which the unit builder discarded with every other
        // control character. See AWordHyphenatedAtALineEnd_IsRejoinedFromARealPdf.
        string path = SyntheticPdf.WriteHyphenated(SyntheticPdf.TempPath("hyphen"),
            ("A state-", "of-the-art baseline was used for comparison."));

        var snapshot = await ExtractAsync(path);
        var units = new ReadingUnitBuilder(new ReadingUnitBuilderOptions(NarrationFilterSettings.Default)).Build(snapshot);
        var planner = new NarrationPlanner();
        var plan = await planner.BuildPlanAsync(snapshot, units, NarrationFilterSettings.Default);
        string spoken = string.Join(" ", plan.Segments.Select(s => s.SpokenText));

        // The mid-word hyphens survive intact.
        Assert.Contains("of-the-art baseline was used for comparison.", spoken);
    }

    [Fact]
    public async Task AWordHyphenatedAtALineEnd_IsRejoinedFromARealPdf()
    {
        string path = SyntheticPdf.WriteHyphenated(SyntheticPdf.TempPath("softhyphen"),
            ("The estimator is unbiased under the stated assump-", "tions and remains consistent in large samples."));

        var snapshot = await ExtractAsync(path);
        var units = new ReadingUnitBuilder(new ReadingUnitBuilderOptions(NarrationFilterSettings.Default)).Build(snapshot);
        var plan = await new NarrationPlanner().BuildPlanAsync(snapshot, units, NarrationFilterSettings.Default);
        string spoken = string.Join(" ", plan.Segments.Select(s => s.SpokenText));

        Assert.Contains("under the stated assumptions and remains consistent", spoken);
    }

    [Fact]
    public async Task SentenceCrossingALineBreak_StaysOneUnitWithDisjointRects()
    {
        string path = SyntheticPdf.WriteHyphenated(SyntheticPdf.TempPath("crossline"),
            ("The retrieval pipeline was", "evaluated against a strong baseline."));

        var snapshot = await ExtractAsync(path);
        var units = new ReadingUnitBuilder(new ReadingUnitBuilderOptions(NarrationFilterSettings.Default)).Build(snapshot);

        Assert.NotEmpty(units);
        var unit = units[0];
        Assert.Contains("retrieval pipeline", unit.OriginalText);
        Assert.Contains("strong baseline", unit.OriginalText);

        // Individual word anchors stay on their own source line, including a sentence spanning lines.
        Assert.True(unit.Anchors.Count > 2);
        var rects = unit.Anchors.SelectMany(a => a.Rects).ToArray();
        Assert.DoesNotContain(rects, r => r.IsEmpty);
        float midGap = (rects.Min(r => r.Bottom) + rects.Max(r => r.Top)) / 2;
        Assert.All(rects, r => Assert.True(r.Bottom <= midGap || r.Top >= midGap));
    }

    [Fact]
    public async Task TextlessPage_ReportsMissingTextRatherThanSucceedingSilently()
    {
        string path = SyntheticPdf.WriteTextless(SyntheticPdf.TempPath("textless"), pageCount: 2);
        var snapshot = await ExtractAsync(path);

        Assert.Equal(2, snapshot.PageCount);
        foreach (var page in snapshot.Pages)
        {
            Assert.False(page.Coverage.TextLayerPresent);
            Assert.Equal(0, page.Coverage.CharCount);
            Assert.True(page.Coverage.IsSparse);
            // An empty transcript must never be reported as a successful narration.
            Assert.NotEmpty(page.Coverage.Warnings);
        }
    }

    [Fact]
    public async Task CharBoxes_AgreeWithThePageText()
    {
        string path = SyntheticPdf.WriteSingleColumn(SyntheticPdf.TempPath("charbox"),
            ["Supercalifragilistic text for indexing."]);
        var snapshot = await ExtractAsync(path);
        var page = snapshot.Pages[0]!;

        Assert.NotEmpty(page.Chars);
        foreach (var c in page.Chars)
        {
            Assert.InRange(c.Index, 0, page.Text.Length - 1);
            // Every marking glyph has a real box; a zero-area box would make a highlight invisible.
            if (!char.IsWhiteSpace(page.Text[c.Index]))
                Assert.True(c.Rect.Width > 0 && c.Rect.Height > 0,
                    $"glyph '{page.Text[c.Index]}' at index {c.Index} has an empty box");
        }
    }

    [Fact]
    public async Task LineRects_StayInsideTheirPage()
    {
        string path = SyntheticPdf.WriteSingleColumn(SyntheticPdf.TempPath("bounds"),
            ["First line of text.", "Second line of text.", "Third line of text."]);
        var snapshot = await ExtractAsync(path);
        var page = snapshot.Pages[0]!;

        Assert.NotEmpty(page.Lines);
        foreach (var line in page.Lines)
        {
            Assert.True(line.Rect.Left >= -1f, $"line {line.LineId} starts left of the page: {line.Rect}");
            Assert.True(line.Rect.Right <= page.PageWidth + 1f, $"line {line.LineId} runs off the right edge: {line.Rect} (page width {page.PageWidth})");
            Assert.True(line.Rect.Top >= -1f, $"line {line.LineId} starts above the page: {line.Rect}");
            Assert.True(line.Rect.Bottom <= page.PageHeight + 1f, $"line {line.LineId} runs below the page: {line.Rect}");
        }
    }

    [Fact]
    public async Task ReadingOrder_IsContiguousFromZero()
    {
        string path = SyntheticPdf.WriteSingleColumn(SyntheticPdf.TempPath("order"),
            ["One.", "Two.", "Three.", "Four.", "Five."]);
        var snapshot = await ExtractAsync(path);
        var page = snapshot.Pages[0]!;

        var orders = page.Blocks.Select(b => b.Order).OrderBy(o => o).ToList();
        Assert.Equal(Enumerable.Range(0, orders.Count), orders);
    }
}
